#!/usr/bin/env bash
# Bundle item 170 law_sub20_21_pre_videos (thread "Videos: Law and Justice committee meetings", 22 Nov 2569,
# asked by the 3x-daily routine). RUN AFTER 148_law_notices_1122 (which adds the two meetings as upcoming cards).
# Puts two BEFORE-meeting videos on parliamentx.com/law/2569/sub-law.html (Law subcommittee, คณะอนุกรรมาธิการการกฎหมาย):
#   meeting 20/2569, Tue 24 Nov 2569 10.00, CA 327 (notice ว1068, ref 11225919, Rpublic=1)     -> media on DATA key "20|2026-11-24"
#   meeting 21/2569, Thu 26 Nov 2569 10.00, CA 429 (notice ว1068.01, ref 11225932, Rpublic=1)  -> media on DATA key "21|2026-11-26"
# The cancelled 19 Nov meeting (also numbered 20, "20|2026-11-19") stays cancelled with NO media (checked below).
# 1080x1920, Thai voice + English subtitles burned in (one version), kind="pre". Agenda items only, invitees by agency only.
# SELF-CONTAINED (shared folder over its cap): mp4/vtt/poster files + media.json embedded below as base64 tar.gz.
# Surgical: replaces only "media" of those two meetings in the DATA line of sub-law.html and in sub-law.json, fills the CAPS
# caption tracks (law-20p, law-21p), makes the video share pages (video_share.py, CARD_BIG=1) and re-applies no_video_dl.
# video_offload.py in run_bundle.sh then moves the two mp4s to video-1 (same as every video item).
# Sub videos do not change the home newest-4 list or snapshot (main meetings only). Idempotent; no git, no network.
set -euo pipefail
: "${HUB:?HUB not set}"; BUILD=${BUILD:-/mnt/project-files/archive/build}
TMPP=$(mktemp -d)
trap 'rm -rf "$TMPP"' EXIT
sed -n '/^__PAYLOAD_BELOW__$/,$p' "$0" | tail -n +2 | base64 -d | tar -xz -C "$TMPP"
PAY="$TMPP/pay"
L="$HUB/law/2569"
for f in sub-law.html sub-law.json index.html; do
  test -f "$L/$f" || { echo "170_law_sub20_21_pre_videos: $L/$f missing" >&2; exit 1; }; done
python3 - "$L" <<'PY'
import json, sys
ms = json.load(open(sys.argv[1] + '/sub-law.json', encoding='utf-8'))
k = {(m['n'], m['date']) for m in ms}
assert (20, '2026-11-24') in k and (21, '2026-11-26') in k, '170_law_sub20_21_pre_videos: sub-law.json has no 24/26 Nov meetings: run 148_law_notices_1122 first'
PY
# files must be whole: 1080x1920 video of the listed length, WEBVTT captions
for v in sub-law-v20pre:100 sub-law-v21pre:124; do f=${v%%:*}; want=${v##*:}
  test -s "$PAY/files/media/$f.mp4" -a -s "$PAY/files/media/$f.th.vtt" || { echo "170_law_sub20_21_pre_videos: payload $f missing" >&2; exit 1; }
  dur=$(ffprobe -v error -show_entries format=duration -of csv=p=0 "$PAY/files/media/$f.mp4")
  python3 -c "import sys; sys.exit(0 if abs(float('$dur')-$want)<1.5 else 1)" || { echo "170_law_sub20_21_pre_videos: $f length $dur, expected ~$want s" >&2; exit 1; }
  wh=$(ffprobe -v error -select_streams v:0 -show_entries stream=width,height -of csv=p=0 "$PAY/files/media/$f.mp4"); [ "$wh" = "1080,1920" ] || { echo "170_law_sub20_21_pre_videos: $f size $wh" >&2; exit 1; }
  head -1 "$PAY/files/media/$f.th.vtt" | grep -q '^WEBVTT' || { echo "170_law_sub20_21_pre_videos: $f vtt header" >&2; exit 1; }
done
mkdir -p "$L/media" "$L/img"
(cd "$PAY/files" && find . -type f) | while read -r f; do
  cmp -s "$PAY/files/$f" "$L/$f" || cp -f "$PAY/files/$f" "$L/$f"; cmp -s "$PAY/files/$f" "$L/$f"; done
python3 - "$L" "$PAY/media.json" <<'PY'
import json, os, sys
L, PJ = sys.argv[1], sys.argv[2]
MEDIA = json.load(open(PJ, encoding='utf-8'))['MEDIA']
CMP = dict(ensure_ascii=False, separators=(',', ':'))
ser = lambda a: json.dumps(a, **CMP).replace('</', '<\\/')
dec = json.JSONDecoder()
changed = []
def sized(md):
    md = json.loads(json.dumps(md))
    for v in [md['video']] + md['videos']:
        v['size'] = os.path.getsize(os.path.join(L, v['src']))
    return md
def jline(lines, prefix, dumps):
    idx = [i for i, l in enumerate(lines) if l.startswith(prefix)]
    assert len(idx) == 1, f'170_law_sub20_21_pre_videos: {prefix} line not found once'
    body = lines[idx[0]][len(prefix):]; val, end = dec.raw_decode(body); tail = body[end:]
    for d in dumps:
        if prefix + d(val) + tail == lines[idx[0]]:
            return idx[0], val, tail, d
    raise SystemExit(f'170_law_sub20_21_pre_videos: {prefix} line does not round-trip; not touching it')
p = os.path.join(L, 'sub-law.html'); orig = open(p, encoding='utf-8').read(); lines = orig.split('\n')
i, arr, tail, d = jline(lines, 'const DATA=', (ser, lambda a: json.dumps(a, ensure_ascii=False)))
keys = {f"{m['n']}|{m['date']}": m for m in arr}
for k, md in MEDIA.items():
    assert k in keys, f'170_law_sub20_21_pre_videos: sub-law.html meeting {k} not on the page'
    keys[k]['media'] = sized(md)
lines[i] = 'const DATA=' + d(arr) + tail
i, caps, tail, d = jline(lines, 'const CAPS=', (lambda a: json.dumps(a, ensure_ascii=False), ser))
for md in MEDIA.values():
    v = md['video']; caps[v['ck']] = open(os.path.join(L, v['vtt']), encoding='utf-8').read()
lines[i] = 'const CAPS=' + d(caps) + tail
t = '\n'.join(lines)
if t != orig:
    open(p, 'w', encoding='utf-8').write(t); changed.append('sub-law.html')
p = os.path.join(L, 'sub-law.json'); raw = open(p, encoding='utf-8').read(); ms = json.loads(raw)
fmt = [k for k in (dict(indent=1), dict(), dict(separators=(',', ':'))) if json.dumps(ms, ensure_ascii=False, **k) == raw.rstrip('\n')]
assert fmt, '170_law_sub20_21_pre_videos: sub-law.json does not round-trip; not touching it'
mk = {f"{m['n']}|{m['date']}": m for m in ms}
for k, md in MEDIA.items():
    assert k in mk, f'170_law_sub20_21_pre_videos: sub-law.json meeting {k} missing'
    mk[k]['media'] = sized(md)
out = json.dumps(ms, ensure_ascii=False, **fmt[0]) + ('\n' if raw.endswith('\n') else '')
if out != raw:
    open(p, 'w', encoding='utf-8').write(out); changed.append('sub-law.json')
print('170_law_sub20_21_pre_videos: changed', ', '.join(changed) or 'nothing (already applied)')
PY
CARD_BIG=1 python3 "$BUILD/video_share.py" "$L" https://parliamentx.com/law/2569 2569
python3 "$BUILD/no_video_dl.py" "$L/s"
python3 "$BUILD/no_video_dl.py" --check "$L"
for f in v-law-20-pre v-law-21-pre; do test -f "$L/s/$f.html" || { echo "170_law_sub20_21_pre_videos: share page s/$f.html missing" >&2; exit 1; }; done
python3 - "$L" <<'PY'
import json, sys
L = sys.argv[1]
t = open(f'{L}/sub-law.html', encoding='utf-8').read()
vs = [l for l in t.split('\n') if l.startswith('const VSHARE=')] or [l for l in t.split(';') if 'const VSHARE=' in l]
assert vs and '"20":' in vs[0] and '"21":' in vs[0], '170_law_sub20_21_pre_videos: VSHARE missing 20/21'
ms = {(m['n'], m['date']): m for m in json.load(open(f'{L}/sub-law.json', encoding='utf-8'))}
for k in ((20, '2026-11-24'), (21, '2026-11-26')):
    v = ms[k]['media']['video']; assert v['kind'] == 'pre' and v['ck'] == 'law-%dp' % k[0], f'170_law_sub20_21_pre_videos: {k} media'
c = ms.get((20, '2026-11-19'))
assert c is None or (c.get('cancelled') and not c.get('media')), '170_law_sub20_21_pre_videos: the cancelled 19 Nov meeting must have no video'
assert '"law-20p"' in t and '"law-21p"' in t, '170_law_sub20_21_pre_videos: CAPS tracks missing'
print('170_law_sub20_21_pre_videos OK')
PY
exit 0
